export default function install(app){const root=app.getMount('content-assistant');const el=(tag,text,style={})=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;Object.assign(n.style,style);return n;};const wrap={minWidth:'0',maxWidth:'100%',overflowWrap:'anywhere',boxSizing:'border-box'};const intro=el('p','Consulta guiada de solo lectura · No utiliza IA generativa.',{fontSize:'11px',color:'#64748b'}),form=el('form'),input=el('textarea',null,{width:'100%',padding:'9px',...wrap}),send=el('button','Preguntar'),clear=el('button','Limpiar'),examples=el('div'),out=el('div',null,{maxHeight:'380px',overflowY:'auto',...wrap});input.rows=2;input.maxLength=400;input.placeholder='¿Cuántos dashboards hay?';input.setAttribute('aria-label','Pregunta sobre el contenido');send.type='submit';clear.type='button';out.setAttribute('aria-live','polite');for(const b of [send,clear])Object.assign(b.style,{padding:'8px',margin:'5px',border:'1px solid #cbd5e1',borderRadius:'7px',cursor:'pointer'});form.append(input,send,clear);root.replaceChildren(intro,examples,form,out);let busy=false,disposed=false,portal=null,revision=0;
 const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 function interpret(q){const n=norm(q);if(/eliminar|borrar|editar|publicar|compartir|modificar|crear/.test(n))return{message:'Este asistente es de solo lectura.'};if(/dependencia|depende|utiliza|impacto|seleccionado|relaciones/.test(n))return{message:'Consulta las pestañas UTILIZA y UTILIZADO POR en Detalle y relaciones. El análisis inverso revisa hasta 60 elementos y no es exhaustivo.'};if(!/busca|muestra|dame|lista|cuant|ultim|recient|mapa|dashboard|capa|escena|aplicacion|contenido|elemento/.test(n))return{message:'Puedo buscar por tipo y palabras clave, contar elementos y listar los más recientes.'};const types=[[/\b(?:dashboards?|cuadros? de mando)\b/,'Dashboard'],[/\bescenas?\b/,'Web Scene'],[/\bmapas?(?: web)?\b/,'Web Map'],[/\b(?:capas?(?: de entidades)?|feature services?)\b/,'Feature Service'],[/\baplicaciones?(?: web)?\b/,'Web Mapping Application']];const match=types.find(([r])=>r.test(n));let s=n.replace(/[¿?¡!.,;:]/g,' ');if(match)s=s.replace(new RegExp(match[0].source,'g'),' ');s=s.replace(/\b(busca|buscar|buscame|muestra|mostrar|muestrame|dame|lista|listar|cuantos|cuantas|cuanto|cuanta|ultimos|ultimas|recientes|reciente|hay|tenemos|tengo|existen|ver|quiero|por favor|contenido|contenidos|elemento|elementos|todos|todas|los|las|el|la|un|una|de|del|sobre|con|en|mi|mis|organizacion|nuestra|nuestro|portal|web)\b/g,' ').replace(/\s+/g,' ').trim();if(/\b(propietario|usuario|dueno|antes|despues|fecha|ayer|hoy|mes|ano|publicos|privados|sin uso)\b/.test(s))return{message:'Todavía no interpreto filtros por propietario, fecha, acceso o contenido sin uso.'};const terms=s.split(' ').filter(Boolean);if(terms.some(t=>!/^[-a-z0-9_]+$/.test(t)))return{message:'Usa palabras clave sencillas sin operadores.'};return{type:match?.[1],terms,count:/cuant/.test(n)};}
 async function ask({question}){question=String(question||'').trim().slice(0,400);if(!question||busy)return{busy};const token=++revision,box=el('div',null,{borderTop:'1px solid #dbe3ed',padding:'10px 0',...wrap}),answer=el('div','Consultando…');box.append(el('div',question,{fontWeight:'700',...wrap}),answer);out.append(box);while(out.children.length>4)out.firstElementChild.remove();const intent=interpret(question);if(intent.message){answer.textContent=intent.message;return{supported:false,answer:intent.message};}busy=true;send.disabled=true;try{if(!portal){const Portal=await app.import('esri/portal/Portal');portal=new Portal({url:app.portalUrl});await portal.load();}const org=portal.user?.orgId||portal.id,user=portal.user?.username;if(!org&&!user)throw new Error('No se ha podido identificar tu sesión');const parts=[org?`orgid:${org}`:`owner:${user}`];if(intent.type)parts.push(`type:"${intent.type}"`);intent.terms.forEach(t=>parts.push(`"${t}"`));const r=await portal.queryItems({query:parts.join(' AND '),start:1,num:intent.count?1:app.config.resultLimit,sortField:'modified',sortOrder:'desc'});if(disposed||token!==revision)return{cancelled:true};answer.replaceChildren(el('p',`Interpretación: ${intent.count?'contar':'listar'} ${intent.type||'todos los tipos'}${intent.terms.length?' · '+intent.terms.join(', '):''}.`),el('div',`${r.total.toLocaleString('es-ES')} coincidencias`,{fontWeight:'700'}),el('p',org?'Contenido de la organización accesible con tu sesión.':'Contenido propio accesible con tu sesión.'));const rows=r.results||r.items||[];if(!intent.count){answer.append(el('p','Hasta 8 resultados, por última modificación.'));for(const it of rows){const card=el('div',null,{padding:'8px',marginTop:'6px',border:'1px solid #dbe3ed',...wrap});const a=el('a','Abrir en ArcGIS ↗',{display:'inline-block',marginTop:'6px'});a.href=it.itemPageUrl||`${portal.url.replace(/\/$/,'')}/home/item.html?id=${encodeURIComponent(it.id)}`;a.target='_blank';a.rel='noopener noreferrer';card.append(el('div',it.title,{fontWeight:'700',...wrap}),el('div',`${it.type} · ${it.owner}`,{fontSize:'11px',...wrap}),a);answer.append(card);}}return{total:r.total,returned:intent.count?0:rows.length,interpretation:intent};}catch(e){if(!disposed&&token===revision)answer.textContent=`No se pudo consultar: ${e.message}`;return{error:e.message};}finally{busy=false;if(!disposed)send.disabled=false;}}
 const submit=e=>{e.preventDefault();ask({question:input.value});},reset=()=>{revision++;out.replaceChildren();input.value='';};form.addEventListener('submit',submit);clear.addEventListener('click',reset);for(const q of ['Busca mapas de agua','¿Cuántos dashboards hay?','Últimos elementos']){const b=el('button',q,{margin:'3px',padding:'5px',cursor:'pointer'});b.type='button';b.addEventListener('click',()=>{input.value=q;ask({question:q});});examples.append(b);}const action=app.actions.register('ask-content-assistant',ask);app.onCleanup(()=>{disposed=true;revision++;action.remove();form.removeEventListener('submit',submit);clear.removeEventListener('click',reset);root.replaceChildren();});}